import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') ptr++;
            return hasNextByte();
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }
    }

    static class Rect {
        int x1, x2, y1, y2;

        Rect(int x1, int y1, int x2, int y2) {
            this.x1 = Math.min(x1, x2);
            this.x2 = Math.max(x1, x2);
            this.y1 = Math.min(y1, y2);
            this.y2 = Math.max(y1, y2);
        }

        int distTo(Rect other) {
            int dx = Math.max(0, Math.max(this.x1, other.x1) - Math.min(this.x2, other.x2));
            int dy = Math.max(0, Math.max(this.y1, other.y1) - Math.min(this.y2, other.y2));
            return dx + dy;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        if (!scanner.hasNext()) return;

        int xi = scanner.nextInt();
        int yi = scanner.nextInt();
        int xf = scanner.nextInt();
        int yf = scanner.nextInt();

        int n = scanner.nextInt();

        int totalNodes = n + 2;
        Rect[] rects = new Rect[totalNodes];

        rects[0] = new Rect(xi, yi, xi, yi);
        for (int i = 1; i <= n; i++) {
            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            int x2 = scanner.nextInt();
            int y2 = scanner.nextInt();
            rects[i] = new Rect(x1, y1, x2, y2);
        }
        rects[n + 1] = new Rect(xf, yf, xf, yf);

        int[] dist = new int[totalNodes];
        boolean[] visited = new boolean[totalNodes];
        Arrays.fill(dist, Integer.MAX_VALUE);

        dist[0] = 0;

        for (int i = 0; i < totalNodes; i++) {
            int u = -1;
            int minDist = Integer.MAX_VALUE;

            for (int v = 0; v < totalNodes; v++) {
                if (!visited[v] && dist[v] < minDist) {
                    minDist = dist[v];
                    u = v;
                }
            }

            if (u == -1 || u == n + 1) {
                break;
            }

            visited[u] = true;

            for (int v = 0; v < totalNodes; v++) {
                if (!visited[v]) {
                    int w = rects[u].distTo(rects[v]);
                    if (dist[u] + w < dist[v]) {
                        dist[v] = dist[u] + w;
                    }
                }
            }
        }

        System.out.println(dist[n + 1]);
    }
}
